CREATE TABLE auth_providers (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,provider_type TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL DEFAULT 0,display_name TEXT,client_id TEXT,client_secret TEXT,issuer_url TEXT,scopes TEXT DEFAULT 'openid email profile',extra_config TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')),sync_mtime INTEGER NOT NULL DEFAULT 0);
CREATE TABLE event_deliveries (outbox_id INTEGER NOT NULL REFERENCES event_outbox(id) ON DELETE CASCADE,endpoint_id TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY (outbox_id,endpoint_id));
CREATE TABLE event_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,bucket TEXT NOT NULL,object_key TEXT NOT NULL,source TEXT NOT NULL,occurred_at INTEGER NOT NULL,payload_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER,claimed_by TEXT,claimed_at INTEGER,delivered_at INTEGER,last_error TEXT,created_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE external_identities (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider_id INTEGER NOT NULL REFERENCES auth_providers(id) ON DELETE CASCADE,external_sub TEXT NOT NULL,email TEXT,display_name TEXT,last_login TEXT,raw_claims TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),email_verified INTEGER NOT NULL DEFAULT 0,sync_mtime INTEGER NOT NULL DEFAULT 0,UNIQUE(provider_id,external_sub));
CREATE TABLE group_mapping_rules (id INTEGER PRIMARY KEY AUTOINCREMENT,provider_id INTEGER REFERENCES auth_providers(id) ON DELETE CASCADE,priority INTEGER NOT NULL DEFAULT 0,match_type TEXT NOT NULL,match_field TEXT NOT NULL DEFAULT 'email',match_value TEXT NOT NULL,group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT (datetime('now')),sync_mtime INTEGER NOT NULL DEFAULT 0,rule_uid TEXT);
CREATE TABLE group_members (group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY (group_id,user_id));
CREATE TABLE group_permissions (id INTEGER PRIMARY KEY AUTOINCREMENT,group_id INTEGER NOT NULL REFERENCES groups(id) ON DELETE CASCADE,actions TEXT NOT NULL,resources TEXT NOT NULL,effect TEXT NOT NULL DEFAULT 'Allow',conditions_json TEXT);
CREATE TABLE groups (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,description TEXT DEFAULT '',created_at TEXT NOT NULL DEFAULT (datetime('now')),sync_mtime INTEGER NOT NULL DEFAULT 0);
CREATE TABLE lifecycle_failures (id INTEGER PRIMARY KEY AUTOINCREMENT,rule_name TEXT NOT NULL,run_id INTEGER,occurred_at INTEGER NOT NULL,bucket TEXT NOT NULL,object_key TEXT NOT NULL,error_message TEXT NOT NULL,FOREIGN KEY (rule_name) REFERENCES lifecycle_state(rule_name) ON DELETE CASCADE,FOREIGN KEY (run_id) REFERENCES lifecycle_run_history(id) ON DELETE SET NULL);
CREATE TABLE lifecycle_run_history (id INTEGER PRIMARY KEY AUTOINCREMENT,rule_name TEXT NOT NULL,triggered_by TEXT NOT NULL DEFAULT 'unknown',started_at INTEGER NOT NULL,finished_at INTEGER,objects_scanned INTEGER NOT NULL DEFAULT 0,objects_affected INTEGER NOT NULL DEFAULT 0,objects_skipped INTEGER NOT NULL DEFAULT 0,bytes_affected INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,FOREIGN KEY (rule_name) REFERENCES lifecycle_state(rule_name) ON DELETE CASCADE);
CREATE TABLE lifecycle_state (rule_name TEXT PRIMARY KEY,last_run_at INTEGER,next_due_at INTEGER NOT NULL,last_status TEXT NOT NULL,objects_affected_lifetime INTEGER NOT NULL DEFAULT 0,bytes_affected_lifetime INTEGER NOT NULL DEFAULT 0,leader_instance_id TEXT,leader_expires_at INTEGER,continuation_token TEXT,paused INTEGER NOT NULL DEFAULT 0,cursor_scope TEXT);
CREATE TABLE listener_cursors (listener_name TEXT PRIMARY KEY,last_event_id INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE maintenance_failures (id INTEGER PRIMARY KEY AUTOINCREMENT,job_id INTEGER NOT NULL,object_key TEXT NOT NULL,error TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE maintenance_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL DEFAULT 'reencrypt',bucket TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',phase TEXT NOT NULL DEFAULT 'counting',objects_total INTEGER,objects_done INTEGER NOT NULL DEFAULT 0,objects_skipped INTEGER NOT NULL DEFAULT 0,objects_failed INTEGER NOT NULL DEFAULT 0,bytes_done INTEGER NOT NULL DEFAULT 0,continuation_token TEXT,last_error TEXT,triggered_by TEXT,leader_instance_id TEXT,leader_expires_at INTEGER,created_at INTEGER NOT NULL,started_at INTEGER,finished_at INTEGER,updated_at INTEGER NOT NULL,params TEXT);
CREATE TABLE permissions (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,actions TEXT NOT NULL,resources TEXT NOT NULL,effect TEXT NOT NULL DEFAULT 'Allow',conditions_json TEXT);
CREATE TABLE replication_failures (id INTEGER PRIMARY KEY AUTOINCREMENT,rule_name TEXT NOT NULL,run_id INTEGER,occurred_at INTEGER NOT NULL,source_key TEXT NOT NULL,dest_key TEXT NOT NULL,error_message TEXT NOT NULL,FOREIGN KEY (rule_name) REFERENCES replication_state(rule_name) ON DELETE CASCADE);
CREATE TABLE replication_object_failures (rule_name TEXT NOT NULL,source_key TEXT NOT NULL,consecutive_failures INTEGER NOT NULL DEFAULT 0,last_error TEXT,last_failed_at INTEGER,PRIMARY KEY (rule_name,source_key));
CREATE TABLE replication_parity (rule_name TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'idle',scanned_at INTEGER,progress_scanned INTEGER NOT NULL DEFAULT 0,in_sync INTEGER NOT NULL DEFAULT 0,outcome_json TEXT,last_error TEXT,leader_instance_id TEXT,leader_expires_at INTEGER,updated_at INTEGER,progress_total INTEGER NOT NULL DEFAULT 0);
CREATE TABLE replication_parity_objects (rule_name TEXT NOT NULL,side TEXT NOT NULL,dest_key TEXT NOT NULL,sha256 TEXT,size INTEGER NOT NULL,etag TEXT,stored_etag TEXT,updated_at INTEGER NOT NULL,created_at INTEGER,PRIMARY KEY (rule_name,side,dest_key));
CREATE TABLE replication_run_history (id INTEGER PRIMARY KEY AUTOINCREMENT,rule_name TEXT NOT NULL,triggered_by TEXT NOT NULL DEFAULT 'unknown',started_at INTEGER NOT NULL,finished_at INTEGER,objects_scanned INTEGER NOT NULL DEFAULT 0,objects_copied INTEGER NOT NULL DEFAULT 0,objects_skipped INTEGER NOT NULL DEFAULT 0,objects_deleted INTEGER NOT NULL DEFAULT 0,bytes_copied INTEGER NOT NULL DEFAULT 0,errors INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,delta_passthrough INTEGER NOT NULL DEFAULT 0,bytes_egress_saved INTEGER NOT NULL DEFAULT 0,reconstructed INTEGER NOT NULL DEFAULT 0,FOREIGN KEY (rule_name) REFERENCES replication_state(rule_name) ON DELETE CASCADE);
CREATE TABLE replication_state (rule_name TEXT PRIMARY KEY,last_run_at INTEGER,next_due_at INTEGER NOT NULL,last_status TEXT NOT NULL,objects_copied_lifetime INTEGER NOT NULL DEFAULT 0,bytes_copied_lifetime INTEGER NOT NULL DEFAULT 0,paused INTEGER NOT NULL DEFAULT 0,continuation_token TEXT,leader_instance_id TEXT,leader_expires_at INTEGER);
CREATE TABLE session_revocations (identity TEXT PRIMARY KEY,revoked_since INTEGER NOT NULL);
CREATE TABLE sync_state (id INTEGER PRIMARY KEY CHECK (id = 1),sync_generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,access_key_id TEXT NOT NULL UNIQUE,secret_access_key TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT (datetime('now')),auth_source TEXT NOT NULL DEFAULT 'local',sync_mtime INTEGER NOT NULL DEFAULT 0);
CREATE INDEX idx_event_outbox_object ON event_outbox(bucket,object_key,occurred_at DESC);
CREATE INDEX idx_event_outbox_recent ON event_outbox(occurred_at DESC,id DESC);
CREATE INDEX idx_event_outbox_status_due ON event_outbox(status,next_attempt_at,occurred_at,id);
CREATE INDEX idx_ext_identity_lookup ON external_identities(provider_id,external_sub);
CREATE INDEX idx_ext_identity_user ON external_identities(user_id);
CREATE INDEX idx_failures_rule ON replication_failures(rule_name,occurred_at DESC);
CREATE INDEX idx_group_mapping_provider ON group_mapping_rules(provider_id);
CREATE INDEX idx_lifecycle_failures_rule ON lifecycle_failures(rule_name,occurred_at DESC);
CREATE INDEX idx_lifecycle_failures_run ON lifecycle_failures(rule_name,run_id,occurred_at DESC);
CREATE INDEX idx_lifecycle_run_history_rule ON lifecycle_run_history(rule_name,started_at DESC);
CREATE UNIQUE INDEX idx_maint_active_bucket ON maintenance_jobs(bucket) WHERE status IN ('queued','running','cancelling');
CREATE INDEX idx_maint_failures_job ON maintenance_failures(job_id,created_at DESC);
CREATE UNIQUE INDEX idx_mapping_rule_uid ON group_mapping_rules(rule_uid);
CREATE INDEX idx_permissions_user ON permissions(user_id);
CREATE INDEX idx_run_history_rule ON replication_run_history(rule_name,started_at DESC);
CREATE INDEX idx_users_access_key ON users(access_key_id);
CREATE UNIQUE INDEX idx_users_name ON users(name);
CREATE TRIGGER trg_auth_providers_mtime_ins AFTER INSERT ON auth_providers WHEN NEW.sync_mtime = 0 BEGIN UPDATE auth_providers SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_auth_providers_mtime_upd AFTER UPDATE ON auth_providers WHEN NEW.sync_mtime = OLD.sync_mtime BEGIN UPDATE auth_providers SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_external_identities_mtime_ins AFTER INSERT ON external_identities WHEN NEW.sync_mtime = 0 BEGIN UPDATE external_identities SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_external_identities_mtime_upd AFTER UPDATE ON external_identities WHEN NEW.sync_mtime = OLD.sync_mtime BEGIN UPDATE external_identities SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_group_mapping_rules_mtime_ins AFTER INSERT ON group_mapping_rules WHEN NEW.sync_mtime = 0 BEGIN UPDATE group_mapping_rules SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_group_mapping_rules_mtime_upd AFTER UPDATE ON group_mapping_rules WHEN NEW.sync_mtime = OLD.sync_mtime BEGIN UPDATE group_mapping_rules SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_group_mapping_rules_uid AFTER INSERT ON group_mapping_rules WHEN NEW.rule_uid IS NULL BEGIN UPDATE group_mapping_rules SET rule_uid = lower(hex(randomblob(16))) WHERE id = NEW.id; END;
CREATE TRIGGER trg_group_permissions_delete_mtime AFTER DELETE ON group_permissions BEGIN UPDATE groups SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = OLD.group_id; END;
CREATE TRIGGER trg_group_permissions_insert_mtime AFTER INSERT ON group_permissions BEGIN UPDATE groups SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.group_id; END;
CREATE TRIGGER trg_group_permissions_update_mtime AFTER UPDATE ON group_permissions BEGIN UPDATE groups SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.group_id; END;
CREATE TRIGGER trg_groups_mtime_ins AFTER INSERT ON groups WHEN NEW.sync_mtime = 0 BEGIN UPDATE groups SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_groups_mtime_upd AFTER UPDATE ON groups WHEN NEW.sync_mtime = OLD.sync_mtime BEGIN UPDATE groups SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_permissions_delete_mtime AFTER DELETE ON permissions BEGIN UPDATE users SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = OLD.user_id; END;
CREATE TRIGGER trg_permissions_insert_mtime AFTER INSERT ON permissions BEGIN UPDATE users SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.user_id; END;
CREATE TRIGGER trg_permissions_update_mtime AFTER UPDATE ON permissions BEGIN UPDATE users SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.user_id; END;
CREATE TRIGGER trg_users_mtime_ins AFTER INSERT ON users WHEN NEW.sync_mtime = 0 BEGIN UPDATE users SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
CREATE TRIGGER trg_users_mtime_upd AFTER UPDATE ON users WHEN NEW.sync_mtime = OLD.sync_mtime BEGIN UPDATE users SET sync_mtime = CAST((julianday('now') - 2440587.5) * 86400000.0 AS INTEGER) WHERE id = NEW.id; END;
